if (
    window.GestiaCore?.procesarIntencion &&
    !["arre", "confirmar", "ok"].includes(cmd)
) {
    try {
                const terminalBrainRoute =
            await routeTerminalNaturalIntent(
                comando,
                {
                    activePatchProposal:
                        window.__SIA7_ACTIVE_VISUAL_PATCH_PROPOSAL__ ||
                        null,
                    lastPatchPreview:
                        readLastPatchPreviewCandidate?.() ||
                        null,
                    traceId:
                        currentTraceId
                }
            );

        console.info(
            "[TERMINAL_BRAIN_ROUTER_41_42]",
            {
                command:
                    comando,
                mode:
                    terminalBrainRoute?.mode,
                confidence:
                    terminalBrainRoute?.confidence,
                reason:
                    terminalBrainRoute?.reason,
                writeAllowed:
                    terminalBrainRoute?.writeAllowed,
                approvalRequiredForWrite:
                    terminalBrainRoute?.approvalRequiredForWrite,
                traceId:
                    currentTraceId
            }
        );

        if (
            terminalBrainRoute?.mode === "CASUAL_NOOP"
        ) {
            recordTerminalLearningIncident({
                category:
                    "TERMINAL_BRAIN_ROUTER",
                status:
                    "success",
                stage:
                    "terminal_brain_router",
                operation:
                    "CASUAL_NOOP",
                reason:
                    terminalBrainRoute.reason ||
                    "CASUAL_WITHOUT_ACTIVE_FLOW",
                symptom:
                    comando,
                fixRule:
                    "Use contextual terminal routing before casual response; do not use repo tools when there is no active flow or technical objective.",
                sourceTraceId:
                    currentTraceId,
                confidence:
                    terminalBrainRoute.confidence || 0.8
            });

            window.renderJarvisResponse?.(
                "Jarvis",
                buildCasualTerminalResponse(comando),
                "info"
            );

            handled =
                true;

            return;
